### C++

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9 + 7;

// 快速幂
ll modExp(ll base, ll exp, ll mod) {
    ll res = 1;
    base %= mod;
    while (exp) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

// 树状数组
struct BIT {
    int n;
    vector<ll> tree;
    BIT(int n) : n(n), tree(n + 1, 0) {}

    void update(int idx, ll val) {
        for (; idx <= n; idx += idx & -idx)
            tree[idx] += val;
    }

    ll query(int idx) {
        ll res = 0;
        for (; idx; idx -= idx & -idx)
            res += tree[idx];
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> r(n), s(n), d(n);
    for (int i = 0; i < n; i++) cin >> r[i];
    for (int i = 0; i < n; i++) cin >> s[i];
    for (int i = 0; i < n; i++) cin >> d[i];

    // 判定值 1 (优质) 或 -1 (普通)
    vector<int> v(n);
    for (int i = 0; i < n; i++) {
        v[i] = (r[i] - s[i] > d[i]) ? 1 : -1;
    }

    // 前缀和
    vector<ll> pre(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        pre[i] = pre[i - 1] + v[i - 1];
    }

    // 离散化
    vector<ll> vals = pre;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    auto getID = [&](ll x) {
        return lower_bound(vals.begin(), vals.end(), x) - vals.begin() + 1;
    };

    BIT bit(vals.size());
    ll countPairs = 0;

    // 统计顺序对
    for (int j = 0; j <= n; j++) {
        int id = getID(pre[j]);
        countPairs += bit.query(id - 1);   // 小于当前值的个数
        bit.update(id, 1);
    }

    ll total = (ll)n * (n + 1) / 2;
    ll invTotal = modExp(total, MOD - 2, MOD);
    ll ans = (countPairs % MOD) * invTotal % MOD;

    cout << ans << "\n";
    return 0;
}
